const raw = $input.first().json;
const body = raw.body ?? raw;

const conexaoId = body.conexaoId || body.conexao_id;
const to = String(body.to || '').replace(/\D/g, '');
const type = body.type;

if (!conexaoId) throw new Error('Campo conexaoId obrigatorio.');
if (!to) throw new Error('Campo to obrigatorio (apenas digitos).');
if (!type) throw new Error('Campo type obrigatorio.');

const sessionTypes = ['text', 'image', 'audio', 'video', 'document', 'sticker', 'location', 'contacts', 'interactive', 'reaction'];
const allowed = ['template', ...sessionTypes];
if (!allowed.includes(type)) {
  throw new Error(`type invalido. Use: ${allowed.join(', ')}`);
}

return [
  {
    json: {
      conexaoId,
      to,
      type,
      template: body.template || null,
      text: body.text || null,
      image: body.image || null,
      audio: body.audio || null,
      video: body.video || null,
      document: body.document || null,
      sticker: body.sticker || null,
      location: body.location || null,
      contacts: body.contacts || null,
      interactive: body.interactive || null,
      reaction: body.reaction || null,
      context: body.context || null
    }
  }
];

const entrada = $('VALIDAR ENTRADA').first().json;
const conexao = $input.first().json;

if (!conexao?.access_token || !conexao?.phone_number_id) {
  throw new Error('Conexao nao encontrada em SAAS_Conexoes.');
}

if (!conexao.apiOficial) {
  throw new Error('Conexao nao e API Oficial.');
}

if (!conexao.contaId) {
  throw new Error('Conexao sem contaId.');
}

return [
  {
    json: {
      ...entrada,
      access_token: conexao.access_token,
      phone_number_id: conexao.phone_number_id,
      waba_id: conexao.waba_id,
      contaId: conexao.contaId
    }
  }
];

const data = $input.first().json;
const payload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: data.to,
  type: data.type
};

if (data.context) payload.context = data.context;

if (data.type === 'template') {
  if (!data.template?.name) throw new Error('template.name obrigatorio para type=template.');
  payload.template = {
    name: data.template.name,
    language: data.template.language || { code: 'pt_BR' },
    components: data.template.components || []
  };
} else if (data.type === 'text') {
  if (!data.text?.body) throw new Error('text.body obrigatorio para type=text.');
  payload.text = data.text;
} else if (data.type === 'image') {
  if (!data.image) throw new Error('image obrigatorio para type=image.');
  payload.image = data.image;
} else if (data.type === 'audio') {
  if (!data.audio) throw new Error('audio obrigatorio para type=audio.');
  payload.audio = data.audio;
} else if (data.type === 'video') {
  if (!data.video) throw new Error('video obrigatorio para type=video.');
  payload.video = data.video;
} else if (data.type === 'document') {
  if (!data.document) throw new Error('document obrigatorio para type=document.');
  payload.document = data.document;
} else if (data.type === 'sticker') {
  if (!data.sticker) throw new Error('sticker obrigatorio para type=sticker.');
  payload.sticker = data.sticker;
} else if (data.type === 'location') {
  if (!data.location) throw new Error('location obrigatorio para type=location.');
  payload.location = data.location;
} else if (data.type === 'contacts') {
  if (!data.contacts) throw new Error('contacts obrigatorio para type=contacts.');
  payload.contacts = data.contacts;
} else if (data.type === 'interactive') {
  if (!data.interactive) throw new Error('interactive obrigatorio para type=interactive.');
  payload.interactive = data.interactive;
} else if (data.type === 'reaction') {
  if (!data.reaction) throw new Error('reaction obrigatorio para type=reaction.');
  payload.reaction = data.reaction;
}

return [
  {
    json: {
      conexaoId: data.conexaoId,
      phone_number_id: data.phone_number_id,
      access_token: data.access_token,
      to: data.to,
      type: data.type,
      meta_payload: payload
    }
  }
];

const prev = $('MONTAR PAYLOAD META').first().json;
const metaRes = $input.first().json;

if (metaRes.error) {
  throw new Error(metaRes.error.message || metaRes.error.error_user_msg || 'Falha ao enviar mensagem na Meta.');
}

const messageId = metaRes.messages?.[0]?.id || null;
const payload = prev.meta_payload;
const type = prev.type;

let mensagem = null;
if (type === 'text') mensagem = payload.text?.body || null;
else if (type === 'template') mensagem = `[template: ${payload.template?.name || 'sem_nome'}]`;
else if (type === 'image') mensagem = payload.image?.caption || '[imagem]';
else if (type === 'video') mensagem = payload.video?.caption || '[video]';
else if (type === 'audio') mensagem = '[audio]';
else if (type === 'document') mensagem = payload.document?.caption || '[documento]';
else if (type === 'sticker') mensagem = '[sticker]';
else if (type === 'location') mensagem = '[localizacao]';
else if (type === 'contacts') mensagem = '[contato]';
else if (type === 'interactive') mensagem = '[interativo]';
else if (type === 'reaction') mensagem = payload.reaction?.emoji || '[reacao]';
else mensagem = `[${type}]`;

return [
  {
    json: {
      conexaoId: prev.conexaoId,
      contaId: $('MESCLAR CONEXAO').first().json.contaId,
      destinatario: prev.to,
      tipo: type,
      mensagem,
      metaMessageId: messageId,
      metaStatus: messageId ? 'sent' : null,
      status: messageId ? 'enviada' : 'erro',
      metaResponse: metaRes
    }
  }
];

const vars = $('VARIAVEIS').first().json;
const prev = $input.first().json;

if (!prev.metaMessageId) {
  return [{ json: { ...prev, chat: { ok: false, skipped: true } } }];
}

const supabaseUrl = (vars.SUPABASE_URL || '').replace(/\/$/, '');
const serviceKey = vars.SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl || supabaseUrl.includes('COLE_SEU')) {
  throw new Error('Defina SUPABASE_URL no no VARIAVEIS.');
}
if (!serviceKey || serviceKey.includes('COLE_SEU')) {
  throw new Error('Defina SUPABASE_SERVICE_ROLE_KEY no no VARIAVEIS.');
}

const tipoMap = {
  text: 'conversation',
  template: 'conversation',
  image: 'imageMessage',
  audio: 'audioMessage',
  video: 'videoMessage',
  document: 'documentMessage',
  sticker: 'stickerMessage',
  location: 'location',
  contacts: 'contacts',
  interactive: 'interactive',
  reaction: 'reaction'
};

const chat = await this.helpers.httpRequest({
  method: 'POST',
  url: `${supabaseUrl}/rest/v1/rpc/f_meta_salvar_mensagem_chat`,
  headers: {
    apikey: serviceKey,
    Authorization: `Bearer ${serviceKey}`,
    'Content-Type': 'application/json',
    Prefer: 'return=representation'
  },
  body: {
    p_conexao_id: prev.conexaoId,
    p_conta_id: prev.contaId,
    p_telefone: prev.destinatario,
    p_mensagem: prev.mensagem,
    p_tipo_mensagem: tipoMap[prev.tipo] || prev.tipo,
    p_from_me: true,
    p_meta_message_id: prev.metaMessageId,
    p_meta_status: prev.metaStatus
  },
  json: true
});

return [{ json: { ...prev, chat } }];

const prev = $('VALIDAR RESPOSTA META').first().json;
const row = $input.first().json;

return [
  {
    json: {
      ok: true,
      mensagemId: row.chat?.mensagemId || null,
      conversaId: row.chat?.conversaId || null,
      conexaoId: prev.conexaoId,
      destinatario: prev.destinatario,
      tipo: prev.tipo,
      metaMessageId: prev.metaMessageId,
      metaStatus: prev.metaStatus,
      status: prev.status
    }
  }
];
